type Job = {
    id: string;
    outcome: 'success' | 'failure';
    value?: unknown;
    message?: string;
};
export async function settleSimulatedJobs(jobs: Job[]): Promise<unknown[]> {
    const promises = jobs.map(job => job.outcome === 'success'
        ? Promise.resolve(job.value)
        : Promise.reject(new Error(job.message)));
    const results = await Promise.allSettled(promises);
    return results.map((result, i) => result.status === 'fulfilled'
        ? { id: jobs[i].id, status: 'fulfilled', value: result.value }
        : { id: jobs[i].id, status: 'rejected', reason: result.reason.message });
}
